package presentation.snippets.s01suspend.slide37

import presentation.support.*
import arrow.continuations.SuspendApp
import kotlinx.coroutines.awaitCancellation

fun main() = SuspendApp {
  try {
    awaitCancellation()
  } finally {
    println("Application stopped")
  }
}
